            Pc1Audio.Loaded realLoaded=ds.loadPcm(2,raw("VOICE"),true);check(realLoaded!=null&&realLoaded.successful&&realLoaded.bytes==63902,"Actual original mode3 stream loaded without static zlib substitution");check(Binary.sha256(ds.bufferBytes(2)).equals(expected),"All63902 actual DS samples match complete original41CF00 programs");check(ds.streamState()[1]==2&&audio.readNativeInt(0x42ab1c)==-1,"Initial full-song fill reaches real native EOF/CloseHandle/raw-1");Pc1OsRegistry.Scalar realFile=registry.findOwner(Pc1DirectSound.nativeFileOwner(1));check(realFile!=null&&!realFile.live()&&registry.lookupFile(realFile.rawWord|3).status==Pc1OsRegistry.Status.CLOSED,"MM/initial native close changes the one physical provider, no alive shadow");ds.setVolume(2,-10000);ds.play(2,0);Thread.sleep(15);ds.stop(2);/*Keep the native loaded/COM pair intact until provider teardown.*/
            Pc1Audio.Loaded loaded=ds.loadPcm(0,raw("SYNTH"),true);check(loaded!=null&&loaded.successful,"Actual own-mode1 stream and buffer created");liveWord[0]=audio.readNativeInt(0x42ab1c);check(registry.lookupFile(liveWord[0]).status==Pc1OsRegistry.Status.LIVE,"Raw FILE publication resolves exact registered current source");audio.writeNativeInt(0x42ab1c,liveWord[0]|3);long[] initial=ds.streamState();ds.setVolume(0,-10000);ds.play(0,1);Thread.sleep(800);long[] after=ds.streamState();check(after[5]>initial[5]&&after[2]==0,"Native MM uses low2-tagged live raw FILE and fills while Java blocked");check(audio.readNativeInt(0x43de74)==17&&audio.readNativeInt(0x43de78)==1,"Stream extra and static coefficient-return extra retain independent owners");savedProgress[0]=after[5];
            captured=ds.snapshotBoundary(()->{owners[0]=save(pe::save);owners[1]=save(registry::save);owners[2]=save(o->space.saveLayout(o,lease->-1));return ds.capture(audio);});Files.write(out.resolve("physical.snapshot"),save(captured::save));Files.write(out.resolve("effect-pe.snapshot"),owners[0]);Files.write(out.resolve("os-registry.snapshot"),owners[1]);Files.write(out.resolve("guest-layout.snapshot"),owners[2]);check(audio.readNativeInt(0x42ab1c)==(liveWord[0]|3),"Proof hash preserves actual file cursor and raw tag; snapshot never repairs alias");ds.stop(0);ds.closeStream();
